const rising = ($input.first().json.related_queries || {}).rising || [];
const s = $('Store Settings').first().json;
const asked = [s.search_phrase, s.trends_term].map(t => String(t || '').toLowerCase().trim());
const terms = [...new Set(rising.map(r => String(r.query || '').trim()).filter(t => t && !asked.includes(t.toLowerCase())))].slice(0, 10);
return [{ json: { candidates: terms } }];

const s = $('Store Settings').first().json;
let terms = [];
if ($('Pick Trend Terms (via Ask Venice)').isExecuted) {
  const out = $('Pick Trend Terms (via Ask Venice)').first().json.output || {};
  terms = (out.terms || []).filter(t => typeof t === 'string' && t.trim()).slice(0, 2);
}
return [{ json: { run_id: s.run_id, angle: s.angle, source: 'google_trends', status: terms.length ? 'ok' : 'empty',
  kept_count: 0, dropped_count: 0, trend_terms: terms, context: s.context || null } }];

const s = $('Store Settings').first().json;
const max = s.max_reddit;
const seen = new Map();
for (const it of $input.all()) {
  for (const p of (it.json.posts || [])) {
    if (!p || !p.id || seen.has(p.id)) continue;
    seen.set(p.id, p);
  }
}
const isReddit = (u) => { const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i); return !m || /(^|\.)(reddit\.com|redd\.it)$/i.test(m[1]); };
const ranked = [...seen.values()]
  .filter(p => (p.score || 0) >= s.reddit_min_score && (p.num_comments || 0) >= s.reddit_min_comments)
  .sort((a, b) => ((b.score || 0) + (b.num_comments || 0)) - ((a.score || 0) + (a.num_comments || 0)))
  .slice(0, max);
return ranked.map(p => ({ json: {
  source: 'reddit',
  source_id: 'reddit:' + p.id,
  title: String(p.title || '').slice(0, 300),
  url: p.permalink ? 'https://www.reddit.com' + p.permalink : (p.url && /reddit\.com\/r\/[^\/]+\/comments\//i.test(p.url) ? p.url : 'https://www.reddit.com/comments/' + p.id),
  linked_url: p.url && /^https?:/i.test(p.url) && !isReddit(p.url) ? p.url : '',
  published_at: p.created_at_iso || (p.created_utc ? new Date(p.created_utc * 1000).toISOString() : null),
  text: String(p.selftext || '').replace(/\s+/g, ' ').slice(0, 600),
  engagement: (p.score || 0) + (p.num_comments || 0),
} }));

const max = $('Store Settings').first().json.max_hn;
const seen = new Map();
for (const it of $input.all()) {
  for (const h of (it.json.hits || [])) {
    if (!h || !h.objectID || seen.has(h.objectID)) continue;
    seen.set(h.objectID, h);
  }
}
const ranked = [...seen.values()].sort((a, b) => (b.points || 0) - (a.points || 0)).slice(0, max);
return ranked.map(h => ({ json: {
  source: 'hacker_news',
  source_id: 'hn:' + h.objectID,
  title: String(h.title || '').slice(0, 300),
  url: 'https://news.ycombinator.com/item?id=' + h.objectID,
  linked_url: h.url || '',
  published_at: h.created_at || null,
  text: String(h.story_text || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 600),
  engagement: (h.points || 0) + (h.num_comments || 0),
} }));

const s = $('Store Settings').first().json;
const cands = $input.all().map(i => i.json).filter(c => c && c.source_id);
const esc = (v) => String(v).replace(/'/g, "\\'");
const run = esc(s.run_id);
const check = s.check_duplicates === true || s.check_duplicates === 'true';
// Same run: the same post already saved by an earlier angle (every run).
const postUrls = [...new Set(cands.map(c => c.url).filter(Boolean))];
const sameRun = postUrls.length ? `AND({run_id}='${run}', OR(${postUrls.map(u => `{url}='${esc(u)}'`).join(',')}))` : '';
// Other runs of the last 7 days: same post or same linked article (scheduled runs only).
const urls = [...new Set(cands.flatMap(c => [c.url, c.linked_url]).filter(Boolean))];
const ors = urls.flatMap(u => [`{url}='${esc(u)}'`, `{linked_url}='${esc(u)}'`]);
const older = check && urls.length ? `AND({run_id}!='${run}', IS_AFTER(CREATED_TIME(), DATEADD(NOW(), -7, 'days')), OR(${ors.join(',')}))` : '';
const parts = [sameRun, older].filter(Boolean);
// FALSE() when there is nothing to look up: Airtable then returns no rows.
const formula = parts.length ? `AND({kept}, OR(${parts.join(',')}))` : 'FALSE()';
return [{ json: { candidates: cands.map((c, i) => ({ ...c, id: 'p' + (i + 1) })), formula } }];

const base = $('Collect Candidates').first().json;
const run = $('Store Settings').first().json.run_id;
const thisRun = new Set(), older = new Set();
if ($('Find Already Reported (Airtable Findings)').isExecuted) {
  for (const r of ($('Find Already Reported (Airtable Findings)').first().json.records || [])) {
    if (r.fields.run_id === run) { if (r.fields.url) thisRun.add(r.fields.url); continue; }
    if (r.fields.url) older.add(r.fields.url);
    if (r.fields.linked_url) older.add(r.fields.linked_url);
  }
}
const candidates = base.candidates.map(c => {
  let repeat = '';
  if (thisRun.has(c.url)) repeat = 'found by another angle';
  else if (older.has(c.url) || (!!c.linked_url && older.has(c.linked_url))) repeat = 'already reported';
  return { ...c, repeat };
});
const fresh = candidates.filter(c => !c.repeat);
const posts = fresh.map(c => JSON.stringify({ id: c.id, title: c.title, text: c.text, links_to: c.linked_url || null })).join('\n');
return [{ json: { candidates, fresh_count: fresh.length, posts } }];

const base = $('Mark Repeats').first().json;
// The filter answer is always there: a failed model call stops this workflow and "WF3" reports it.
const dec = {};
for (const d of ($('Filter Posts (via Ask Venice)').first().json.output.decisions || [])) dec[d.id] = d;
const rows = base.candidates.map(c => {
  let kept = false, reason = '', summary = '';
  if (c.repeat) { reason = c.repeat; }
  else if (dec[c.id]) { kept = dec[c.id].keep === true; reason = kept ? '' : String(dec[c.id].reason || '').slice(0, 200); summary = String(dec[c.id].summary || '').slice(0, 400); }
  else { reason = 'no filter decision'; }
  return { ...c, kept, drop_reason: reason, summary: summary || c.title };
});
return [{ json: { rows } }];

const s = $('Store Settings').first().json;
const rows = $input.first().json.rows;
const recs = rows.map(r => ({ fields: {
  title: r.title, run_id: s.run_id, angle: s.angle, source: r.source, url: r.url,
  ...(r.linked_url ? { linked_url: r.linked_url } : {}),
  ...(r.published_at ? { published_at: r.published_at } : {}),
  summary: r.summary, kept: r.kept, drop_reason: r.drop_reason,
} }));
const out = [];
for (let i = 0; i < recs.length; i += 10) out.push({ json: { records: recs.slice(i, i + 10), typecast: true } });
return out;

const s = $('Store Settings').first().json;
const rows = $('Apply Filter Decisions').isExecuted ? $('Apply Filter Decisions').first().json.rows : [];
const kept = rows.filter(r => r.kept).length;
return [{ json: { run_id: s.run_id, angle: s.angle, source: s.source, status: kept ? 'ok' : 'empty',
  kept_count: kept, dropped_count: rows.length - kept, trend_terms: [], context: s.context || null } }];

const s = $('Store Settings').first().json;
const seen = new Map();
for (const it of $input.all()) {
  for (const t of (it.json.tweets || [])) {
    if (!t || !t.id || seen.has(t.id)) continue;
    seen.set(t.id, t);
  }
}
// The search asks for the like and repost minimums (min_faves, min_retweets) and the window (within_time).
// twitterapi.io still pads thin results with weaker posts (tested 2026-10-28, mostly on 24h searches; since_time made it worse),
// and X has no bookmark operator, so every minimum and the date are checked again here.
const cutoff = Date.now() - s.window * 86400000;
const n = (v) => Number(v || 0);
const isX = (u) => /^https?:\/\/([^\/?#:]+\.)?(x\.com|twitter\.com|t\.co)([\/?#:]|$)/i.test(String(u || ''));
const ranked = [...seen.values()]
  .filter(t => n(t.likeCount) >= s.x_min_likes && n(t.retweetCount) >= s.x_min_retweets && n(t.bookmarkCount) >= s.x_min_bookmarks)
  .filter(t => { const d = new Date(t.createdAt); return !isNaN(d) && d.getTime() >= cutoff; })
  .sort((a, b) => (n(b.likeCount) + n(b.retweetCount) + n(b.bookmarkCount) + n(b.replyCount)) - (n(a.likeCount) + n(a.retweetCount) + n(a.bookmarkCount) + n(a.replyCount)))
  .slice(0, s.max_x);
return ranked.map(t => {
  const user = t.author && t.author.userName ? t.author.userName : '';
  const text = String(t.text || '').replace(/\s+/g, ' ').trim();
  const link = ((t.entities && t.entities.urls) || []).map(u => u.expanded_url).find(u => u && /^https?:/i.test(u) && !isX(u)) || '';
  const when = t.createdAt ? new Date(t.createdAt) : null;
  return { json: {
    source: 'x',
    source_id: 'x:' + t.id,
    title: ((user ? '@' + user + ': ' : '') + text).slice(0, 300),
    url: t.url || ('https://x.com/i/status/' + t.id),
    linked_url: link,
    published_at: when && !isNaN(when) ? when.toISOString() : null,
    text: text.slice(0, 600),
    engagement: n(t.likeCount) + n(t.retweetCount) + n(t.bookmarkCount) + n(t.replyCount),
  } };
});
